/* @lc app=leetcode id=3800 lang=kotlin */ class Solution { fun minimumCost(s: String, t: String, flipCost: Int, swapCost: Int, crossCost: Int): Long = s.indices.count { s[it] == '1' && t[it] == '0' }.let { a -> s.indices.count { s[it] == '0' && t[it] == '1' }.let { b -> minOf(a, b).let { p -> Math.abs(a - b).let { r -> p * minOf(2L * flipCost, swapCost.toLong()) + (r / 2) * minOf(2L * flipCost, crossCost.toLong() + swapCost) + (r % 2) * flipCost.toLong() } } } } }